11	  {
12	    variants: {
13	      variant: {
14	        default: "bg-primary text-primary-foreground hover:bg-primary/90",
15	        destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90",
16	        outline: "border border-input bg-background hover:bg-accent hover:text-accent-foreground",
17	        secondary: "bg-secondary text-secondary-foreground hover:bg-secondary/80",
18	        ghost: "hover:bg-accent hover:text-accent-foreground",
19	        link: "text-primary underline-offset-4 hover:underline",
20	      },
21	      size: {
22	        default: "h-10 px-4 py-2",
23	        sm: "h-9 rounded-md px-3",
24	        lg: "h-11 rounded-md px-8",
25	        icon: "h-10 w-10",
26	      },
27	    },
28	    defaultVariants: {
29	      variant: "default",
30	      size: "default",
31	    },
32	  },
33	);
34	
35	export interface ButtonProps
36	  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
37	    VariantProps<typeof buttonVariants> {
38	  asChild?: boolean;
39	}
40	
41	const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
42	  ({ className, variant, size, asChild = false, ...props }, ref) => {
43	    const Comp = asChild ? Slot : "button";
44	    return <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props} />;
45	  },
46	);
47	Button.displayName = "Button";
48	
49	export { Button, buttonVariants };
